validator:
function validate(input) {
  const [{ Orders = [] }] = input;
  const seen = new Set();
  for (const [id, date, customer, invoice] of Orders) {
    if (id === null) return 'Every order needs an order_id.';
    if (seen.has(id)) return `order_id ${id} appears twice in Orders.`;
    seen.add(id);
    if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return `Order ${id} needs an order_date like 2020-09-15.`;
    if (customer === null || invoice === null) return `Order ${id} needs a customer_id and an invoice.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  // Small sets use few months and customers so groups collide; 2020-01 and 2021-01 share a month number.
  const months = small ? ['2020-01', '2020-02', '2021-01'] : Array.from({ length: 30 }, (_, i) => `${2019 + Math.floor(i / 12)}-${String(1 + i % 12).padStart(2, '0')}`);
  const invoices = [5, 10, 15, 19, 20, 20, 21, 30, 55, 77, 90];
  const count = small ? Math.floor(rand() * 9) : 2000;
  const customers = small ? 3 : 400;
  const Orders = [];
  for (let id = 1; id <= count; id++) {
    const day = String(1 + Math.floor(rand() * 28)).padStart(2, '0');
    const invoice = small ? pick(invoices) : Math.floor(rand() * 100);
    Orders.push([id, `${pick(months)}-${day}`, 1 + Math.floor(rand() * customers), invoice]);
  }
  return [{ Orders }];
}
